class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def areAnagrams(root1, root2):
    from collections import deque, Counter

    q1, q2 = deque([root1]), deque([root2])

    while q1 and q2:
        l1, l2 = len(q1), len(q2)
        if l1 != l2:
            return 0

        level1, level2 = [], []

        for _ in range(l1):
            node = q1.popleft()
            level1.append(node.val)
            if node.left:
                q1.append(node.left)
            if node.right:
                q1.append(node.right)

        for _ in range(l2):
            node = q2.popleft()
            level2.append(node.val)
            if node.left:
                q2.append(node.left)
            if node.right:
                q2.append(node.right)

        if Counter(level1) != Counter(level2):
            return 0

    return 1 if not q1 and not q2 else 0
